
const $=s=>document.querySelector(s);let step=0;let photo='assets/cabbage-seller.png';const initial={name:'배추',category:'채소',origin:'국내산',country:'중국',unit:'포기',quantity:20,price:2500,discount:40,duration:24,description:'오늘 들어온 국내산 배추예요.\n겉잎까지 싱싱하게 보관했어요.'};let data={...initial};const won=n=>Number(n).toLocaleString('ko-KR');const sale=()=>Math.round(data.price*(1-data.discount/100));const titles=['사진 촬영 안내','상품 정보 입력','등록 전 확인','등록 완료'];const categories=['채소','육류','축산물','과일','생선','어패류','건어물','가공식품','유제품','즉석식품','곡류','견과/두류','조미료','반찬'];let notice='';
const svg=p=>`<svg viewBox="0 0 24 24"><path d="${p}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;const icons=['M4 8h16v12H4z M3 4h18v4H3z M10 12h4','M5 3h14v18H5z M12 8v8 M8 12h8','M3 10l9-7 9 7v11h-7v-7h-4v7H3z','M4 3h16v14h-8l-5 4v-4H4z M9 7v5 M15 7v5','M8 6a4 4 0 108 0 4 4 0 00-8 0 M4 21v-3a8 5 0 0116 0v3'];$('.nav').innerHTML=['상품 관리','상품 등록','홈','도움말','마이페이지'].map((t,i)=>`<button class="${i===1?'active':''}" data-nav="${i}">${svg(icons[i])}${t}</button>`).join('');$('.nav').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.nav==='1'){step=0;render()}else toast('상품 등록 흐름을 확인하는 시안입니다.')};
function toast(t){$('.toast').textContent=t;$('.toast').classList.remove('hidden');setTimeout(()=>$('.toast').classList.add('hidden'),2300)}
const options=(arr,v)=>arr.map(x=>`<option ${String(v)===String(x)?'selected':''}>${x}</option>`).join('');const escape=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function progress(){return `<div class="progress" aria-label="${step+1}단계">${[0,1,2].map(i=>`<i class="${i<=step?'on':''}"></i>`).join('')}</div>`}function render(){notice='';$('.head b').textContent=step===2?'등록 전 확인':step===3?'등록 완료':'상품 등록';$('.steps').innerHTML=titles.map((t,i)=>`<button data-step="${i}" class="${i===step?'on':''}">0${i+1}　${t}</button>`).join('');$('.steps').onclick=e=>{const b=e.target.closest('button');if(b){step=+b.dataset.step;render()}};
if(step===0){$('#content').innerHTML=progress()+`<p class="eyebrow">01 · 상품 사진</p><h1>판매할 상품을<br>사진으로 알려주세요</h1><p class="intro">상품이 잘 보이도록 가까이 찍어주세요.<br>사진을 바탕으로 상품 정보 입력을 도와드려요.</p><div class="photo-guide"><img src="${photo}" alt="상품을 가까이 촬영한 배추 사진 예시"><div class="frame"></div><span class="photo-tag">✓ 상품이 중앙에, 선명하게</span></div><div class="tips"><b>이렇게 찍으면 좋아요</b><br>밝은 곳에서 상품 전체를 담아주세요.<br>여러 상품보다 한 종류씩 찍어주세요.</div><button class="secondary" id="album">앨범에서 사진 선택</button>`;$('#action').innerHTML='<button class="primary" id="next">사진 촬영하기</button>';$('#next').onclick=()=>{step=1;render();toast('예시 사진으로 상품 정보를 채웠어요. 확인해주세요.')};$('#album').onclick=()=>$('#upload').click()}
if(step===1){$('#content').innerHTML=progress()+`<p class="eyebrow">02 · 상품 정보</p><h1>상품 정보를 확인해주세요</h1><p class="intro">사진으로 채운 정보가 맞는지 확인하고,<br>판매할 수량과 가격을 입력해주세요.</p><div class="photo-row"><img src="${photo}" alt="등록할 상품 사진"><button class="add-photo" id="change"><span>＋</span>사진 변경</button></div><section class="group"><h2>어떤 상품인가요?</h2><label class="field"><span>상품명 <small class="ai">사진 인식 예시</small></span><input name="name" maxlength="50" value="${escape(data.name)}" required><p class="hint">상품명이 다르면 직접 수정해주세요.</p></label><label class="field"><span>카테고리</span><select name="category">${options(categories,data.category)}</select></label><div class="field"><span>원산지</span><div class="chips" role="group" aria-label="원산지 선택">${['국내산','외국산'].map(v=>`<button type="button" class="chip ${data.origin===v?'selected':''}" data-origin="${v}" aria-pressed="${data.origin===v}">${v}</button>`).join('')}</div></div><label class="field ${data.origin==='외국산'?'':'hidden'}" id="country"><span>생산 국가</span><select name="country">${options(['중국','베트남','태국','필리핀','미국','기타'],data.country)}</select></label><div class="two"><label class="field"><span>판매 단위</span><select name="unit">${options(['포기','바구니','박스','팩','개','100g','kg'],data.unit)}</select></label><label class="field"><span>판매 수량</span><input name="quantity" type="number" min="1" max="9999" value="${data.quantity}"></label></div></section><section class="group"><h2>얼마에 판매할까요?</h2><label class="field"><span>할인 전 가격 · 1${escape(data.unit)} 기준</span><input name="price" type="number" min="1" max="99999999" value="${data.price}" inputmode="numeric"></label><div class="two"><label class="field"><span>할인율</span><select name="discount">${[10,20,30,40,50,60,70,80,90].map(n=>`<option value="${n}" ${+data.discount===n?'selected':''}>${n}%</option>`).join('')}</select></label><label class="field"><span>판매 기간</span><select name="duration">${[1,2,3,6,12,24].map(n=>`<option value="${n}" ${+data.duration===n?'selected':''}>${n}시간</option>`).join('')}</select></label></div><div class="price-result"><span>할인 적용 판매가</span><strong id="sale">${won(sale())}<small>원</small></strong></div><p class="hint">판매가는 할인 전 가격과 할인율로 자동 계산돼요.<br>판매 기간이 지나면 상품 판매가 종료돼요.</p></section><label class="field"><span>상품 설명 <small style="color:#89958c;font-weight:400">선택</small></span><textarea name="description" maxlength="500" placeholder="상품 상태나 보관 방법을 알려주세요">${escape(data.description)}</textarea></label><p class="error" role="alert" id="error"></p>`;$('#action').innerHTML='<button class="primary" id="next">등록 전 확인하기</button>';$('#change').onclick=()=>$('#upload').click();document.querySelectorAll('[name]').forEach(el=>el.oninput=()=>{data[el.name]=['price','discount','quantity','duration'].includes(el.name)?Number(el.value):el.value;$('#sale').innerHTML=won(sale())+'<small>원</small>'});document.querySelectorAll('[data-origin]').forEach(b=>b.onclick=()=>{data.origin=b.dataset.origin;document.querySelectorAll('[data-origin]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});$('#country').classList.toggle('hidden',data.origin!=='외국산')});$('#next').onclick=()=>{if(!data.name.trim()||!Number.isInteger(data.quantity)||data.quantity<1||data.quantity>9999||!Number.isFinite(data.price)||data.price<1||data.price>99999999){$('#error').textContent='상품명과 올바른 수량·가격을 입력해주세요.';$('#error').scrollIntoView({block:'center'});return}step=2;render()}}
if(step===2){$('#content').innerHTML=progress()+`<p class="eyebrow">03 · 최종 확인</p><h1>이대로 등록할까요?</h1><p class="intro">손님에게 보일 상품 정보를 확인해주세요.</p><img class="preview-photo" src="${photo}" alt="등록할 상품"><span class="pill">${escape(data.category)} · ${escape(data.origin==='외국산'?data.country:data.origin)}</span><h2 class="product-title">${escape(data.origin)} ${escape(data.name)}</h2><p class="store">홍길네 채소가게 · 서원시장</p><div class="price"><span class="discount">${data.discount}%</span><b>${won(sale())}원</b><del>${won(data.price)}원</del><span class="store">/ ${escape(data.unit)}</span></div><div class="spec"><div><span>판매 수량</span>${data.quantity}${escape(data.unit)}</div><div><span>판매 기간</span>등록 후 ${data.duration}시간</div></div><p class="description">${escape(data.description||'추가 설명이 없어요.')}</p><button class="secondary" id="edit">상품 정보 수정하기</button>`;$('#action').innerHTML='<button class="primary" id="publish">상품 등록하기</button>';$('#edit').onclick=()=>{step=1;render()};$('#publish').onclick=()=>{step=3;render()}}
if(step===3){$('#content').innerHTML=`<div class="success"><div class="success-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5 10 17.5 19 7.5"/></svg></div><h1>상품이 등록되었어요</h1><p class="intro">이제 손님들이 상품을 확인할 수 있어요.</p><div class="success-card"><img src="${photo}" alt="등록 완료 상품"><div><b>${escape(data.name)}</b><p>${won(sale())}원 · ${data.quantity}${escape(data.unit)}</p></div></div><div class="check-note">✓<span>등록 후 ${data.duration}시간 동안 판매해요.<br>상품 관리에서 수량과 판매 상태를 확인하세요.</span></div><button class="secondary" id="again">다른 상품도 등록하기</button></div>`;$('#action').innerHTML='<button class="primary" id="manage">등록한 상품 확인하기</button>';$('#again').onclick=()=>{data={...initial};step=0;render()};$('#manage').onclick=()=>{step=2;render();toast('등록한 상품의 미리보기입니다.')}}
$('#content').scrollTop=0;history.replaceState(null,'','#'+['photo','form','review','done'][step])}
$('.back').onclick=()=>{if(step>0){step--;render()}else toast('상품 등록의 첫 단계입니다.')};$('#upload').onchange=e=>{const f=e.target.files[0];if(f){if(!f.type.startsWith('image/')){toast('이미지 파일을 선택해주세요.');return}photo=URL.createObjectURL(f);step=1;render();toast('선택한 사진의 상품 정보를 직접 확인해주세요.')}};const h=location.hash.slice(1);if(['photo','form','review','done'].includes(h))step=['photo','form','review','done'].indexOf(h);if(new URLSearchParams(location.search).has('capture'))document.body.classList.add('capture');render();
